using System.Drawing.Drawing2D;
using System.Diagnostics;
using System.Drawing.Text;
namespace StokTakipUygulamasi;

internal static class Theme
{
    internal static readonly Color Background=Color.FromArgb(6,0,16), Surface=Color.FromArgb(10,4,26), Input=Color.FromArgb(23,15,42), Border=Color.FromArgb(46,31,68), Text=Color.FromArgb(246,243,255), Muted=Color.FromArgb(185,174,205), Accent=Color.FromArgb(195,145,255), Glow=Color.FromArgb(132,0,255), Primary=Color.FromArgb(91,35,165), Hover=Color.FromArgb(42,22,76), Danger=Color.FromArgb(124,54,75);
    internal static bool Motion => SystemInformation.IsMenuAnimationEnabled && !SystemInformation.HighContrast;
    internal static Color Mix(Color a,Color b,double t){t=Math.Clamp(t,0,1);return Color.FromArgb((int)(a.R+(b.R-a.R)*t),(int)(a.G+(b.G-a.G)*t),(int)(a.B+(b.B-a.B)*t));}
    internal static double Ease(double t)=>1-Math.Pow(1-Math.Clamp(t,0,1),3);
    internal static GraphicsPath Rounded(RectangleF r,float radius){var p=new GraphicsPath();float d=Math.Min(radius*2,Math.Min(r.Width,r.Height));if(d<=0){p.AddRectangle(r);return p;}p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.Right-d,r.Y,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.X,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
    internal static void Animate(Control c,int ms,Action<double> frame,Action? complete=null){if(!Motion){frame(1);complete?.Invoke();return;}var clock=Stopwatch.StartNew();var timer=new System.Windows.Forms.Timer{Interval=15};EventHandler? disposed=null;void Stop(){timer.Stop();timer.Dispose();c.Disposed-=disposed;}disposed=(_,_)=>Stop();c.Disposed+=disposed;timer.Tick+=(_,_)=>{if(c.IsDisposed){Stop();return;}double t=Math.Min(1,clock.Elapsed.TotalMilliseconds/ms);frame(Ease(t));if(t>=1){Stop();complete?.Invoke();}};frame(0);timer.Start();}
    internal static void Fade(Form f,int ms=260){if(!Motion){f.Opacity=1;return;}f.Opacity=0.05;Animate(f,ms,t=>f.Opacity=.05+.95*t);}
    internal static void Apply(Control root){foreach(Control c in root.Controls){switch(c){case GlowLabel:break;case MotionButton:break;case BentoCard:break;case DataGridView g:StyleGrid(g);break;case TextBoxBase t:t.BorderStyle=BorderStyle.FixedSingle;InputStyle(t);break;case ComboBox b:b.FlatStyle=FlatStyle.Flat;InputStyle(b);break;case NumericUpDown n:n.BorderStyle=BorderStyle.FixedSingle;InputStyle(n);break;case DateTimePicker d:d.CalendarMonthBackground=Surface;d.CalendarForeColor=Text;d.CalendarTitleBackColor=Primary;d.CalendarTitleForeColor=Text;break;case Label l:l.ForeColor=Muted;break;case TableLayoutPanel:case FlowLayoutPanel:case Panel:break;default:c.ForeColor=Text;break;}if(c is not DataGridView and not NumericUpDown and not ComboBox)Apply(c);}}
    static void InputStyle(Control c){c.BackColor=Input;c.ForeColor=Text;var timer=new System.Windows.Forms.Timer{Interval=15};double value=0;timer.Tick+=(_,_)=>{double target=c.Focused?1:0;value+=Math.Clamp(target-value,-.14,.14);c.BackColor=Mix(Input,Hover,value);if(Math.Abs(target-value)<.001)timer.Stop();};void Change(){if(Motion)timer.Start();else c.BackColor=c.Focused?Hover:Input;}c.Enter+=(_,_)=>Change();c.Leave+=(_,_)=>Change();c.Disposed+=(_,_)=>timer.Dispose();}
    static void StyleGrid(DataGridView g){g.BackgroundColor=Surface;g.BorderStyle=BorderStyle.None;g.GridColor=Border;g.CellBorderStyle=DataGridViewCellBorderStyle.SingleHorizontal;g.EnableHeadersVisualStyles=false;g.ColumnHeadersBorderStyle=DataGridViewHeaderBorderStyle.None;g.ColumnHeadersHeightSizeMode=DataGridViewColumnHeadersHeightSizeMode.DisableResizing;g.ColumnHeadersHeight=38;g.RowHeadersVisible=false;g.RowTemplate.Height=34;g.DefaultCellStyle=new DataGridViewCellStyle{BackColor=Surface,ForeColor=Text,SelectionBackColor=Primary,SelectionForeColor=Color.White,Padding=new Padding(7,0,7,0)};g.AlternatingRowsDefaultCellStyle.BackColor=Color.FromArgb(16,9,34);g.ColumnHeadersDefaultCellStyle=new DataGridViewCellStyle{BackColor=Input,ForeColor=Accent,Font=new Font("Segoe UI",9,FontStyle.Bold),Padding=new Padding(7,0,7,0),SelectionBackColor=Input,SelectionForeColor=Accent};foreach(DataGridViewRow r in g.Rows)r.Height=34;g.DataBindingComplete+=(_,_)=>{foreach(DataGridViewRow r in g.Rows)r.Height=34;};int hover=-1;var levels=new Dictionary<int,double>();var timer=new System.Windows.Forms.Timer{Interval=15};void Redraw(int row){if(row>=0&&row<g.Rows.Count)g.InvalidateRow(row);}void Change(int row){int old=hover;hover=row;if(row>=0&&!levels.ContainsKey(row))levels[row]=0;if(Theme.Motion)timer.Start();else{levels.Clear();if(row>=0)levels[row]=1;Redraw(old);Redraw(row);}}timer.Tick+=(_,_)=>{bool moving=false;foreach(int row in levels.Keys.ToArray()){double target=row==hover?1:0;double value=levels[row]+Math.Clamp(target-levels[row],-.15,.15);levels[row]=value;Redraw(row);if(value<=0&&target==0)levels.Remove(row);if(Math.Abs(value-target)>.001)moving=true;}if(!moving)timer.Stop();};g.CellMouseEnter+=(_,e)=>Change(e.RowIndex);g.CellMouseLeave+=(_,_)=>Change(-1);g.DataBindingComplete+=(_,_)=>{levels.Clear();hover=-1;timer.Stop();};g.CellFormatting+=(_,e)=>{if(e.RowIndex>=0&&levels.TryGetValue(e.RowIndex,out double value))e.CellStyle.BackColor=Mix(e.CellStyle.BackColor,Hover,value);};g.Disposed+=(_,_)=>timer.Dispose();}
}

internal sealed class MotionButton:Button
{
    readonly System.Windows.Forms.Timer timer=new(){Interval=15};double progress;bool over,down;readonly bool primary,danger;
    internal MotionButton(string text,bool primary=false,bool danger=false){Text=text;this.primary=primary;this.danger=danger;FlatStyle=FlatStyle.Flat;FlatAppearance.BorderSize=0;Cursor=Cursors.Hand;ForeColor=Theme.Text;BackColor=Theme.Surface;Font=new Font("Segoe UI",9,FontStyle.Bold);SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.ResizeRedraw,true);timer.Tick+=(_,_)=>{double target=over||Focused?1:0;progress+=Math.Clamp(target-progress,-.13,.13);Invalidate();if(Math.Abs(target-progress)<.001)timer.Stop();};}
    void Change(){if(Theme.Motion)timer.Start();else{progress=over||Focused?1:0;Invalidate();}}
    protected override void OnMouseEnter(EventArgs e){base.OnMouseEnter(e);over=true;Change();}
    protected override void OnMouseLeave(EventArgs e){base.OnMouseLeave(e);over=false;down=false;Change();}
    protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);down=true;Invalidate();}
    protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);down=false;Invalidate();}
    protected override void OnGotFocus(EventArgs e){base.OnGotFocus(e);Change();}
    protected override void OnLostFocus(EventArgs e){base.OnLostFocus(e);down=false;Change();}
    protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.Clear(Parent?.BackColor??Theme.Surface);g.SmoothingMode=SmoothingMode.AntiAlias;var normal=danger?Theme.Danger:primary?Theme.Primary:Theme.Input;var hot=danger?Color.FromArgb(166,72,100):primary?Color.FromArgb(120,54,210):Theme.Hover;var fill=Enabled?Theme.Mix(normal,hot,progress):Theme.Surface;if(down)fill=Theme.Mix(fill,Theme.Background,.25);var r=new RectangleF(1,1,Width-3,Height-3);using var path=Theme.Rounded(r,7);using var brush=new SolidBrush(fill);g.FillPath(brush,path);using var pen=new Pen(Theme.Mix(Theme.Border,Theme.Accent,progress*.8));g.DrawPath(pen,path);TextRenderer.DrawText(g,Text,Font,ClientRectangle,Enabled?Theme.Text:Theme.Muted,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.SingleLine);if(Focused&&ShowFocusCues)ControlPaint.DrawFocusRectangle(g,Rectangle.Inflate(ClientRectangle,-5,-5),Theme.Accent,fill);}
    protected override void Dispose(bool disposing){if(disposing)timer.Dispose();base.Dispose(disposing);}
}

internal sealed class GlowLabel:Label
{
    internal double Reveal{get;set;}=1;
    internal GlowLabel(string text,float size=16){Text=text;Font=new Font("Segoe UI",size,FontStyle.Bold);ForeColor=Theme.Text;Dock=DockStyle.Fill;TextAlign=ContentAlignment.MiddleLeft;SetStyle(ControlStyles.UserPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.ResizeRedraw,true);}
    protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;var bg=Parent?.BackColor??Theme.Background;g.Clear(bg);g.TextRenderingHint=TextRenderingHint.AntiAliasGridFit;using var fmt=new StringFormat{Alignment=TextAlign==ContentAlignment.MiddleCenter?StringAlignment.Center:StringAlignment.Near,LineAlignment=StringAlignment.Center,Trimming=StringTrimming.EllipsisCharacter,FormatFlags=StringFormatFlags.NoWrap};var rect=new RectangleF(4,0,Math.Max(1,Width-8),Height);for(int radius=4;radius>=1;radius--){using var b=new SolidBrush(Color.FromArgb((int)(12*Reveal),Theme.Accent));for(int i=0;i<8;i++){double a=i*Math.PI/4;var shifted=rect;shifted.Offset((float)Math.Cos(a)*radius,(float)Math.Sin(a)*radius);g.DrawString(Text,Font,b,shifted,fmt);}}using var front=new SolidBrush(Theme.Mix(bg,ForeColor,Reveal));g.DrawString(Text,Font,front,rect,fmt);}
}
